// DualMaterialID identifies a registered material in a DualGridTileset.
type DualMaterialID uint16

// DualMaskStyle selects the procedural corner-mask silhouette style generated by NewDualGridMask.
type DualMaskStyle int

const (
	// DualMaskSoft produces smooth rounded quarter-circle corner transitions.
	DualMaskSoft DualMaskStyle = iota
	// DualMaskOrganic produces pixel-art rounded borders with deterministic edge jitter.
	DualMaskOrganic
	// DualMaskRocky produces beveled octagonal transitions with a subtle dark boundary rim.
	DualMaskRocky
)

// DefaultDualMaskOrder maps each row-major cell index (0..15) in a 4x4 mask or
// spritesheet to its dual-grid corner bitmask (TL=8, TR=4, BL=2, BR=1).
var DefaultDualMaskOrder = [16]int{2, 5, 11, 3, 9, 7, 15, 14, 4, 12, 13, 10, 0, 1, 6, 8}

const (
	dualGridSaveVersion     = 1
	defaultDualGridChunk    = 16
	dualGridMaskCols        = 4
	dualGridMaskRows        = 4
	dualGridBitmaskCount    = 16
	dualGridRockyRimShade   = uint8(180)
	dualGridOctagonDiagCoef = 0.7071067811865475
)

var dualGridMultiplyMaskBlend = ebiten.Blend{
	BlendFactorSourceRGB:        ebiten.BlendFactorZero,
	BlendFactorDestinationRGB:   ebiten.BlendFactorSourceColor,
	BlendFactorSourceAlpha:      ebiten.BlendFactorZero,
	BlendFactorDestinationAlpha: ebiten.BlendFactorSourceAlpha,
	BlendOperationRGB:           ebiten.BlendOperationAdd,
	BlendOperationAlpha:         ebiten.BlendOperationAdd,
}

type dualMaterialConfig struct {
	maskOrder [16]int
	color     color.RGBA
	hasColor  bool
}

// DualMaterialOption configures a material registered on DualGridTileset.
type DualMaterialOption func(*dualMaterialConfig)

// WithDualMaskOrder overrides the 4x4 row-major bitmask order used when slicing
// a mask or spritesheet. Defaults to DefaultDualMaskOrder.
func WithDualMaskOrder(order [16]int) DualMaterialOption {
	return func(cfg *dualMaterialConfig) {
		cfg.maskOrder = order
	}
}

// WithDualMaterialColor assigns a swatch color used for minimaps, editors, or
// fallback solid rendering when no material image is provided.
func WithDualMaterialColor(col color.RGBA) DualMaterialOption {
	return func(cfg *dualMaterialConfig) {
		cfg.color = col
		cfg.hasColor = true
	}
}

// NewDualGridMask generates a seamless 4*tileSize x 4*tileSize white-on-transparent
// alpha mask covering all 16 dual-grid bitmasks (0..15) arranged in DefaultDualMaskOrder.
func NewDualGridMask(tileSize int, style DualMaskStyle) *ebiten.Image {
	if tileSize <= 0 {
		tileSize = 1
	}

	atlasW := dualGridMaskCols * tileSize
	atlasH := dualGridMaskRows * tileSize
	pixels := make([]byte, atlasW*atlasH*4)

	tsFloat := float64(tileSize)
	organicAmp := math.Min(1.5, tsFloat*0.12)
	rockyRimWidth := math.Min(1.25, tsFloat*0.25)

	for cellIdx := range dualGridBitmaskCount {
		bitmask := DefaultDualMaskOrder[cellIdx]
		cellCol := cellIdx % dualGridMaskCols
		cellRow := cellIdx / dualGridMaskCols
		baseX := cellCol * tileSize
		baseY := cellRow * tileSize

		if bitmask == 0 {
			continue
		}
		if bitmask == 15 {
			for py := range tileSize {
				rowStart := ((baseY+py)*atlasW + baseX) * 4
				for px := range tileSize {
					idx := rowStart + px*4
					pixels[idx] = 255
					pixels[idx+1] = 255
					pixels[idx+2] = 255
					pixels[idx+3] = 255
				}
			}
			continue
		}

		for py := range tileSize {
			v := (float64(py) + 0.5) / tsFloat
			rowStart := ((baseY+py)*atlasW + baseX) * 4
			for px := range tileSize {
				u := (float64(px) + 0.5) / tsFloat
				sd := evalDualGridMaskSDF(bitmask, u, v, style == DualMaskRocky)
				sdPx := sd * tsFloat
				idx := rowStart + px*4

				switch style {
				case DualMaskOrganic:
					hx := px
					if px == 0 || px == tileSize-1 {
						hx = 0
					}
					hy := py
					if py == 0 || py == tileSize-1 {
						hy = 0
					}
					jitter := dualOrganicHash(hx, hy) * organicAmp
					if sdPx+jitter <= 0 {
						pixels[idx] = 255
						pixels[idx+1] = 255
						pixels[idx+2] = 255
						pixels[idx+3] = 255
					}
				case DualMaskRocky:
					if sdPx <= 0 {
						shade := uint8(255)
						if sdPx >= -rockyRimWidth {
							shade = dualGridRockyRimShade
						}
						pixels[idx] = shade
						pixels[idx+1] = shade
						pixels[idx+2] = shade
						pixels[idx+3] = 255
					}
				default:
					cov := Clamp(0.5-sdPx, 0.0, 1.0)
					val := uint8(math.Round(cov * 255.0))
					pixels[idx] = val
					pixels[idx+1] = val
					pixels[idx+2] = val
					pixels[idx+3] = val
				}
			}
		}
	}

	img := ebiten.NewImage(atlasW, atlasH)
	img.WritePixels(pixels)
	return img
}

func evalDualGridMaskSDF(bitmask int, u, v float64, rocky bool) float64 {
	cornerDist := func(du, dv float64) float64 {
		if rocky {
			return max(du, max(dv, (du+dv)*dualGridOctagonDiagCoef))
		}
		return math.Hypot(du, dv)
	}

	switch bitmask {
	case 0:
		return 1.0
	case 15:
		return -1.0
	case 8: // TL
		return cornerDist(u, v) - 0.5
	case 4: // TR
		return cornerDist(1.0-u, v) - 0.5
	case 2: // BL
		return cornerDist(u, 1.0-v) - 0.5
	case 1: // BR
		return cornerDist(1.0-u, 1.0-v) - 0.5
	case 12: // TL | TR (top half)
		return v - 0.5
	case 3: // BL | BR (bottom half)
		return 0.5 - v
	case 10: // TL | BL (left half)
		return u - 0.5
	case 5: // TR | BR (right half)
		return 0.5 - u
	case 14: // !BR
		return 0.5 - cornerDist(1.0-u, 1.0-v)
	case 13: // !BL
		return 0.5 - cornerDist(u, 1.0-v)
	case 11: // !TR
		return 0.5 - cornerDist(1.0-u, v)
	case 7: // !TL
		return 0.5 - cornerDist(u, v)
	case 9: // TL | BR diagonal saddle
		return math.Min(cornerDist(u, v)-0.5, cornerDist(1.0-u, 1.0-v)-0.5)
	case 6: // TR | BL diagonal saddle
		return math.Min(cornerDist(1.0-u, v)-0.5, cornerDist(u, 1.0-v)-0.5)
	default:
		return 1.0
	}
}

func dualOrganicHash(px, py int) float64 {
	h := uint32(px)*374761393 + uint32(py)*668265263
	h = (h ^ (h >> 13)) * 1274126177
	h ^= h >> 16
	// Map to [-1.0, 1.0].
	return float64(h&0xFFFF)/32767.5 - 1.0
}

type dualGridMaterial struct {
	name   string
	color  color.RGBA
	rowImg *ebiten.Image
}

// DualGridTileset stores dual-grid materials and packs their 16 bitmask variants
// into a single GPU atlas of size (16*tileSize) x (numMaterials*tileSize).
type DualGridTileset struct {
	tileSize        int
	materials       []dualGridMaterial
	atlas           *ebiten.Image
	atlasDirty      bool
	defaultSoftMask *ebiten.Image
	version         uint64
}

// NewDualGridTileset creates a DualGridTileset for tiles of tileSize x tileSize pixels.
func NewDualGridTileset(tileSize int) *DualGridTileset {
	if tileSize <= 0 {
		tileSize = defaultTileSize
	}
	return &DualGridTileset{
		tileSize: tileSize,
	}
}

// TileSize returns the pixel size of a single tile in the tileset.
func (t *DualGridTileset) TileSize() int {
	if t == nil {
		return 0
	}
	return t.tileSize
}

// MaterialCount returns the number of registered materials.
func (t *DualGridTileset) MaterialCount() int {
	if t == nil {
		return 0
	}
	return len(t.materials)
}

// MaterialName returns the registered name for id, or "" if id is out of range.
func (t *DualGridTileset) MaterialName(id DualMaterialID) string {
	if t == nil || int(id) >= len(t.materials) {
		return ""
	}
	return t.materials[id].name
}

// MaterialColor returns the swatch color for id, or zero color.RGBA if out of range.
func (t *DualGridTileset) MaterialColor(id DualMaterialID) color.RGBA {
	if t == nil || int(id) >= len(t.materials) {
		return color.RGBA{}
	}
	return t.materials[id].color
}

// AddMaterialWithMask registers a new material by multiplying materialImg against
// each 4x4 cell of mask4x4. If mask4x4 is nil, a default DualMaskSoft mask is
// generated and owned by the tileset.
func (t *DualGridTileset) AddMaterialWithMask(name string, materialImg, mask4x4 *ebiten.Image, opts ...DualMaterialOption) DualMaterialID {
	cfg := dualMaterialConfig{
		maskOrder: DefaultDualMaskOrder,
		color:     color.RGBA{R: 255, G: 255, B: 255, A: 255},
	}
	for _, opt := range opts {
		if opt != nil {
			opt(&cfg)
		}
	}

	if mask4x4 == nil {
		if t.defaultSoftMask == nil {
			t.defaultSoftMask = NewDualGridMask(t.tileSize, DualMaskSoft)
		}
		mask4x4 = t.defaultSoftMask
	}

	ts := t.tileSize
	rowImg := ebiten.NewImage(dualGridBitmaskCount*ts, ts)
	cellImg := ebiten.NewImage(ts, ts)
	defer cellImg.Deallocate()

	maskBounds := mask4x4.Bounds()
	maskCellW := max(1, maskBounds.Dx()/dualGridMaskCols)
	maskCellH := max(1, maskBounds.Dy()/dualGridMaskRows)

	var matDrawOpts, maskDrawOpts, blitOpts ebiten.DrawImageOptions
	maskDrawOpts.Blend = dualGridMultiplyMaskBlend

	fillCol := cfg.color
	if fillCol.A == 0 && materialImg == nil {
		fillCol = color.RGBA{R: 255, G: 255, B: 255, A: 255}
	}

	for cellIdx := range dualGridBitmaskCount {
		bitmask := cfg.maskOrder[cellIdx]
		if bitmask <= 0 || bitmask >= dualGridBitmaskCount {
			continue
		}

		cellCol := cellIdx % dualGridMaskCols
		cellRow := cellIdx / dualGridMaskCols

		cellImg.Clear()
		if materialImg != nil {
			mb := materialImg.Bounds()
			if mb.Dx() > 0 && mb.Dy() > 0 {
				matDrawOpts.GeoM.Reset()
				if mb.Dx() != ts || mb.Dy() != ts {
					matDrawOpts.GeoM.Scale(float64(ts)/float64(mb.Dx()), float64(ts)/float64(mb.Dy()))
				}
				cellImg.DrawImage(materialImg, &matDrawOpts)
			}
		} else {
			cellImg.Fill(fillCol)
		}

		mx0 := maskBounds.Min.X + cellCol*maskCellW
		my0 := maskBounds.Min.Y + cellRow*maskCellH
		maskSub := mask4x4.SubImage(image.Rect(mx0, my0, mx0+maskCellW, my0+maskCellH)).(*ebiten.Image)

		maskDrawOpts.GeoM.Reset()
		if maskCellW != ts || maskCellH != ts {
			maskDrawOpts.GeoM.Scale(float64(ts)/float64(maskCellW), float64(ts)/float64(maskCellH))
		}
		cellImg.DrawImage(maskSub, &maskDrawOpts)

		blitOpts.GeoM.Reset()
		blitOpts.GeoM.Translate(float64(bitmask*ts), 0)
		rowImg.DrawImage(cellImg, &blitOpts)
	}

	id := DualMaterialID(len(t.materials))
	t.materials = append(t.materials, dualGridMaterial{
		name:   name,
		color:  cfg.color,
		rowImg: rowImg,
	})
	t.atlasDirty = true
	t.version++
	return id
}

// AddMaterialSheet registers a pre-authored 4x4 dual-grid spritesheet mapped by
// maskOrder (defaulting to DefaultDualMaskOrder).
func (t *DualGridTileset) AddMaterialSheet(name string, sheet4x4 *ebiten.Image, opts ...DualMaterialOption) DualMaterialID {
	cfg := dualMaterialConfig{
		maskOrder: DefaultDualMaskOrder,
		color:     color.RGBA{R: 255, G: 255, B: 255, A: 255},
	}
	for _, opt := range opts {
		if opt != nil {
			opt(&cfg)
		}
	}

	ts := t.tileSize
	rowImg := ebiten.NewImage(dualGridBitmaskCount*ts, ts)

	if sheet4x4 != nil {
		sb := sheet4x4.Bounds()
		cellW := max(1, sb.Dx()/dualGridMaskCols)
		cellH := max(1, sb.Dy()/dualGridMaskRows)
		var drawOpts ebiten.DrawImageOptions

		for cellIdx := range dualGridBitmaskCount {
			bitmask := cfg.maskOrder[cellIdx]
			if bitmask < 0 || bitmask >= dualGridBitmaskCount {
				continue
			}
			cellCol := cellIdx % dualGridMaskCols
			cellRow := cellIdx / dualGridMaskCols
			sx0 := sb.Min.X + cellCol*cellW
			sy0 := sb.Min.Y + cellRow*cellH
			sub := sheet4x4.SubImage(image.Rect(sx0, sy0, sx0+cellW, sy0+cellH)).(*ebiten.Image)

			drawOpts.GeoM.Reset()
			if cellW != ts || cellH != ts {
				drawOpts.GeoM.Scale(float64(ts)/float64(cellW), float64(ts)/float64(cellH))
			}
			drawOpts.GeoM.Translate(float64(bitmask*ts), 0)
			rowImg.DrawImage(sub, &drawOpts)
		}
	}

	id := DualMaterialID(len(t.materials))
	t.materials = append(t.materials, dualGridMaterial{
		name:   name,
		color:  cfg.color,
		rowImg: rowImg,
	})
	t.atlasDirty = true
	t.version++
	return id
}

// BuildAtlas builds (or rebuilds if dirty) the packed GPU atlas of size
// (16 * tileSize) x (numMaterials * tileSize), where column = bitmask (0..15)
// and row = materialID. Returns nil if no materials are registered.
func (t *DualGridTileset) BuildAtlas() *ebiten.Image {
	if t == nil || len(t.materials) == 0 {
		if t != nil && t.atlas != nil {
			t.atlas.Deallocate()
			t.atlas = nil
		}
		if t != nil {
			t.atlasDirty = false
		}
		return nil
	}

	if t.atlas != nil && !t.atlasDirty {
		return t.atlas
	}

	if t.atlas != nil {
		t.atlas.Deallocate()
		t.atlas = nil
	}

	ts := t.tileSize
	atlas := ebiten.NewImage(dualGridBitmaskCount*ts, len(t.materials)*ts)
	var op ebiten.DrawImageOptions
	for i := range t.materials {
		rowImg := t.materials[i].rowImg
		if rowImg == nil {
			continue
		}
		op.GeoM.Reset()
		op.GeoM.Translate(0, float64(i*ts))
		atlas.DrawImage(rowImg, &op)
	}

	t.atlas = atlas
	t.atlasDirty = false
	return t.atlas
}

// Atlas returns the cached GPU atlas, building it lazily if needed or dirty.
func (t *DualGridTileset) Atlas() *ebiten.Image {
	if t == nil {
		return nil
	}
	if t.atlas == nil || t.atlasDirty {
		return t.BuildAtlas()
	}
	return t.atlas
}

// Dispose deallocates the packed atlas and all internally owned material and mask images.
func (t *DualGridTileset) Dispose() {
	if t == nil {
		return
	}
	if t.atlas != nil {
		t.atlas.Deallocate()
		t.atlas = nil
	}
	if t.defaultSoftMask != nil {
		t.defaultSoftMask.Deallocate()
		t.defaultSoftMask = nil
	}
	for i := range t.materials {
		if t.materials[i].rowImg != nil {
			t.materials[i].rowImg.Deallocate()
			t.materials[i].rowImg = nil
		}
	}
	t.materials = nil
	t.atlasDirty = false
	t.version++
}

// DualGridMapOption configures a DualGridMap.
type DualGridMapOption func(*DualGridMap)

// WithDualGridChunkSize sets the chunk dimension in dual cells (default 16).
func WithDualGridChunkSize(cs int) DualGridMapOption {
	return func(m *DualGridMap) {
		if cs > 0 {
			m.chunkSize = cs
		}
	}
}

// DualGridMap stores a chunked, editor-ready logical tile grid whose corners
// drive seamless dual-grid rendering and RLE JSON serialization.
type DualGridMap struct {
	tiles       []DualMaterialID
	dirtyChunks []bool
	width       int
	height      int
	tileSize    int
	chunkSize   int
	chunksX     int
	chunksY     int
	defaultMat  DualMaterialID
}

// NewDualGridMap creates a width x height DualGridMap filled with defaultMat.
func NewDualGridMap(width, height, tileSize int, defaultMat DualMaterialID, opts ...DualGridMapOption) *DualGridMap {
	if width <= 0 {
		width = 1
	}
	if height <= 0 {
		height = 1
	}
	if tileSize <= 0 {
		tileSize = defaultTileSize
	}

	m := &DualGridMap{
		width:      width,
		height:     height,
		tileSize:   tileSize,
		chunkSize:  defaultDualGridChunk,
		defaultMat: defaultMat,
	}
	for _, opt := range opts {
		if opt != nil {
			opt(m)
		}
	}

	m.initStorage()
	m.Fill(defaultMat)
	return m
}

func (m *DualGridMap) initStorage() {
	// Dual corners span [0..width] x [0..height], i.e. (width+1) x (height+1) dual cells.
	m.chunksX = (m.width + m.chunkSize) / m.chunkSize
	m.chunksY = (m.height + m.chunkSize) / m.chunkSize
	m.tiles = make([]DualMaterialID, m.width*m.height)
	m.dirtyChunks = make([]bool, m.chunksX*m.chunksY)
}

// Width returns the logical grid width in tiles.
func (m *DualGridMap) Width() int { return m.width }

// Height returns the logical grid height in tiles.
func (m *DualGridMap) Height() int { return m.height }

// TileSize returns the pixel size of a single tile.
func (m *DualGridMap) TileSize() int { return m.tileSize }

// ChunkSize returns the chunk span in dual cells.
func (m *DualGridMap) ChunkSize() int { return m.chunkSize }

// ChunksX returns the number of dual-grid chunks along X.
func (m *DualGridMap) ChunksX() int { return m.chunksX }

// ChunksY returns the number of dual-grid chunks along Y.
func (m *DualGridMap) ChunksY() int { return m.chunksY }

// WorldPixelSize returns the full logical map pixel dimensions (width, height).
func (m *DualGridMap) WorldPixelSize() (float64, float64) {
	return float64(m.width * m.tileSize), float64(m.height * m.tileSize)
}

// WorldToTile converts world pixel coordinates (wx, wy) to logical tile indices (tx, ty).
func (m *DualGridMap) WorldToTile(wx, wy float64) (int, int) {
	ts := float64(m.tileSize)
	return int(math.Floor(wx / ts)), int(math.Floor(wy / ts))
}

// TileToWorld returns the world-space top-left pixel coordinates of logical tile (tx, ty).
func (m *DualGridMap) TileToWorld(tx, ty int) (float64, float64) {
	return float64(tx * m.tileSize), float64(ty * m.tileSize)
}

// TileAt returns the material ID at logical tile (tx, ty), or defaultMat if out of bounds.
func (m *DualGridMap) TileAt(tx, ty int) DualMaterialID {
	if tx < 0 || ty < 0 || tx >= m.width || ty >= m.height {
		return m.defaultMat
	}
	return m.tiles[ty*m.width+tx]
}

// SetTile assigns mat to logical tile (tx, ty) and marks every chunk owning any
// of its 4 surrounding dual corners dirty. Returns false if (tx, ty) is out of bounds.
func (m *DualGridMap) SetTile(tx, ty int, mat DualMaterialID) bool {
	if tx < 0 || ty < 0 || tx >= m.width || ty >= m.height {
		return false
	}
	idx := ty*m.width + tx
	if m.tiles[idx] != mat {
		m.tiles[idx] = mat
		m.markTileChunksDirty(tx, ty)
	}
	return true
}

func (m *DualGridMap) markTileChunksDirty(tx, ty int) {
	cs := m.chunkSize
	cx0 := tx / cs
	cx1 := (tx + 1) / cs
	cy0 := ty / cs
	cy1 := (ty + 1) / cs

	m.dirtyChunks[cy0*m.chunksX+cx0] = true
	if cx1 != cx0 {
		m.dirtyChunks[cy0*m.chunksX+cx1] = true
	}
	if cy1 != cy0 {
		m.dirtyChunks[cy1*m.chunksX+cx0] = true
		if cx1 != cx0 {
			m.dirtyChunks[cy1*m.chunksX+cx1] = true
		}
	}
}

// IsChunkDirty reports whether dual-grid chunk (cx, cy) requires re-baking.
func (m *DualGridMap) IsChunkDirty(cx, cy int) bool {
	if cx < 0 || cy < 0 || cx >= m.chunksX || cy >= m.chunksY {
		return false
	}
	return m.dirtyChunks[cy*m.chunksX+cx]
}

// MarkAllDirty marks every chunk in the map dirty for re-baking.
func (m *DualGridMap) MarkAllDirty() {
	for i := range m.dirtyChunks {
		m.dirtyChunks[i] = true
	}
}

// Fill sets every tile in the map to mat and marks all chunks dirty.
func (m *DualGridMap) Fill(mat DualMaterialID) {
	for i := range m.tiles {
		m.tiles[i] = mat
	}
	m.MarkAllDirty()
}

// PaintBrush paints a circular brush of radius tiles centered at (cx, cy) with mat
// and returns the number of tiles whose material changed.
func (m *DualGridMap) PaintBrush(cx, cy, radius int, mat DualMaterialID) int {
	if radius < 0 {
		return 0
	}
	if radius == 0 {
		if cx < 0 || cy < 0 || cx >= m.width || cy >= m.height {
			return 0
		}
		idx := cy*m.width + cx
		if m.tiles[idx] == mat {
			return 0
		}
		m.tiles[idx] = mat
		m.markTileChunksDirty(cx, cy)
		return 1
	}

	minX := max(0, cx-radius)
	maxX := min(m.width-1, cx+radius)
	minY := max(0, cy-radius)
	maxY := min(m.height-1, cy+radius)
	if minX > maxX || minY > maxY {
		return 0
	}

	r2 := radius * radius
	changed := 0
	for ty := minY; ty <= maxY; ty++ {
		dy := ty - cy
		dy2 := dy * dy
		row := ty * m.width
		for tx := minX; tx <= maxX; tx++ {
			dx := tx - cx
			if dx*dx+dy2 > r2 {
				continue
			}
			idx := row + tx
			if m.tiles[idx] != mat {
				m.tiles[idx] = mat
				m.markTileChunksDirty(tx, ty)
				changed++
			}
		}
	}
	return changed
}

// PaintRect paints the inclusive rectangle [x1..x2] x [y1..y2] with mat and
// returns the number of tiles whose material changed.
func (m *DualGridMap) PaintRect(x1, y1, x2, y2 int, mat DualMaterialID) int {
	if x1 > x2 {
		x1, x2 = x2, x1
	}
	if y1 > y2 {
		y1, y2 = y2, y1
	}
	minX := max(0, x1)
	maxX := min(m.width-1, x2)
	minY := max(0, y1)
	maxY := min(m.height-1, y2)
	if minX > maxX || minY > maxY {
		return 0
	}

	changed := 0
	for ty := minY; ty <= maxY; ty++ {
		row := ty * m.width
		for tx := minX; tx <= maxX; tx++ {
			idx := row + tx
			if m.tiles[idx] != mat {
				m.tiles[idx] = mat
				m.markTileChunksDirty(tx, ty)
				changed++
			}
		}
	}
	return changed
}

// FloodFill performs an iterative BFS flood fill starting at (tx, ty), replacing
// contiguous tiles matching the starting material with mat. Returns the count
// of modified tiles, capped at the total map size.
func (m *DualGridMap) FloodFill(tx, ty int, mat DualMaterialID) int {
	if tx < 0 || ty < 0 || tx >= m.width || ty >= m.height {
		return 0
	}
	startIdx := ty*m.width + tx
	target := m.tiles[startIdx]
	if target == mat {
		return 0
	}

	maxTiles := m.width * m.height
	m.tiles[startIdx] = mat
	m.markTileChunksDirty(tx, ty)
	changed := 1

	queue := make([]int, 1, min(maxTiles, 1024))
	queue[0] = startIdx

	for head := 0; head < len(queue) && changed < maxTiles; head++ {
		cur := queue[head]
		cx := cur % m.width
		cy := cur / m.width

		if cx > 0 {
			ni := cur - 1
			if m.tiles[ni] == target {
				m.tiles[ni] = mat
				m.markTileChunksDirty(cx-1, cy)
				queue = append(queue, ni)
				changed++
			}
		}
		if cx+1 < m.width && changed < maxTiles {
			ni := cur + 1
			if m.tiles[ni] == target {
				m.tiles[ni] = mat
				m.markTileChunksDirty(cx+1, cy)
				queue = append(queue, ni)
				changed++
			}
		}
		if cy > 0 && changed < maxTiles {
			ni := cur - m.width
			if m.tiles[ni] == target {
				m.tiles[ni] = mat
				m.markTileChunksDirty(cx, cy-1)
				queue = append(queue, ni)
				changed++
			}
		}
		if cy+1 < m.height && changed < maxTiles {
			ni := cur + m.width
			if m.tiles[ni] == target {
				m.tiles[ni] = mat
				m.markTileChunksDirty(cx, cy+1)
				queue = append(queue, ni)
				changed++
			}
		}
	}

	return changed
}

type dualGridMapSave struct {
	Version    int            `json:"version"`
	Width      int            `json:"width"`
	Height     int            `json:"height"`
	TileSize   int            `json:"tile_size"`
	ChunkSize  int            `json:"chunk_size"`
	DefaultMat DualMaterialID `json:"default_mat"`
	TilesRLE   []uint32       `json:"tiles_rle"`
}

// MarshalJSON encodes the DualGridMap into compact RLE-compressed JSON.
func (m *DualGridMap) MarshalJSON() ([]byte, error) {
	if m == nil {
		return nil, errors.New("katsu2d: cannot marshal nil DualGridMap")
	}

	rle := make([]uint32, 0, min(len(m.tiles)*2, 256))
	for _, v := range m.tiles {
		val := uint32(v)
		n := len(rle)
		if n >= 2 && rle[n-1] == val {
			rle[n-2]++
		} else {
			rle = append(rle, 1, val)
		}
	}

	payload := dualGridMapSave{
		Version:    dualGridSaveVersion,
		Width:      m.width,
		Height:     m.height,
		TileSize:   m.tileSize,
		ChunkSize:  m.chunkSize,
		DefaultMat: m.defaultMat,
		TilesRLE:   rle,
	}
	return json.Marshal(payload)
}

// UnmarshalJSON decodes RLE-compressed JSON into the DualGridMap and marks all chunks dirty.
func (m *DualGridMap) UnmarshalJSON(data []byte) error {
	var payload dualGridMapSave
	if err := json.Unmarshal(data, &payload); err != nil {
		return fmt.Errorf("katsu2d: decode dual grid map: %w", err)
	}
	if payload.Version != dualGridSaveVersion {
		return fmt.Errorf("katsu2d: unsupported dual grid map version %d (want %d)", payload.Version, dualGridSaveVersion)
	}
	if payload.Width <= 0 || payload.Height <= 0 || payload.TileSize <= 0 || payload.ChunkSize <= 0 {
		return fmt.Errorf("katsu2d: invalid dual grid map dimensions %dx%d (tile %d, chunk %d)",
			payload.Width, payload.Height, payload.TileSize, payload.ChunkSize)
	}
	if len(payload.TilesRLE)%2 != 0 {
		return errors.New("katsu2d: odd dual grid RLE stream length")
	}

	totalTiles := payload.Width * payload.Height
	tiles := make([]DualMaterialID, totalTiles)
	decoded := 0
	for i := 0; i < len(payload.TilesRLE); i += 2 {
		count := int(payload.TilesRLE[i])
		val := DualMaterialID(payload.TilesRLE[i+1])
		if count <= 0 || decoded+count > totalTiles {
			return errors.New("katsu2d: invalid dual grid RLE run length")
		}
		for k := range count {
			tiles[decoded+k] = val
		}
		decoded += count
	}
	if decoded != totalTiles {
		return fmt.Errorf("katsu2d: decoded %d dual grid tiles, expected %d", decoded, totalTiles)
	}

	m.width = payload.Width
	m.height = payload.Height
	m.tileSize = payload.TileSize
	m.chunkSize = payload.ChunkSize
	m.defaultMat = payload.DefaultMat
	m.initStorage()
	copy(m.tiles, tiles)
	m.MarkAllDirty()
	return nil
}

// SaveJSON atomically writes the RLE-encoded map JSON to path using a temp file and os.Rename.
func (m *DualGridMap) SaveJSON(path string) error {
	if path == "" {
		return errors.New("katsu2d: cannot save DualGridMap to empty path")
	}
	data, err := m.MarshalJSON()
	if err != nil {
		return err
	}
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return fmt.Errorf("katsu2d: create dual grid map dir %q: %w", dir, err)
	}
	tmpPath := path + ".tmp"
	if err := os.WriteFile(tmpPath, data, 0o644); err != nil {
		return fmt.Errorf("katsu2d: write temp dual grid map %q: %w", tmpPath, err)
	}
	if err := os.Rename(tmpPath, path); err != nil {
		_ = os.Remove(tmpPath)
		return fmt.Errorf("katsu2d: rename dual grid map %q: %w", path, err)
	}
	return nil
}

// LoadJSON reads and decodes an RLE-encoded DualGridMap JSON file from path.
func (m *DualGridMap) LoadJSON(path string) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("katsu2d: read dual grid map %q: %w", path, err)
	}
	return m.UnmarshalJSON(data)
}
